	public long GetResultPartOne()
	{
		long result = 0;

		List<(long, long)> coords = [];
		string[] rows = MyInput.Split("\n");
		
		//parse input
		foreach (string row in rows)
		{
			string[] parts = row.Split(",");
			coords.Add((long.Parse(parts[0]), long.Parse(parts[1])));
		}

		for (int i = 0; i < coords.Count; i++)
		{
			long ax = coords[i].Item1;
			long ay = coords[i].Item2;
			for (int j = i + 1; j < coords.Count; j++)
			{
				long bx = coords[j].Item1;
				long by = coords[j].Item2;
				
				long area = (Math.Abs(ax - bx) + 1) * (Math.Abs(ay - by) + 1);

				if (area > result) result = area;
			}
		}

		return result;
	}
	
	public long GetResultPartTwo()
	{
		List<(int, int)> coords = [];
		string[] rows = MyInput.Split("\n");
		int xSize = 0;
		int ySize = 0;
		
		//first read max x and max y
		foreach (string row in rows)
		{
			string[] parts = row.Split(",");

			int x = int.Parse(parts[0]);
			int y = int.Parse(parts[1]);
			xSize = Math.Max(xSize, x);
			ySize = Math.Max(ySize, y);
			coords.Add((x, y));
		}
		coords.Add(coords[0]);
		
		//create grid
		List<List<char>> grid = new List<List<char>>(ySize + 1);
		
		for (int i = 0; i <= ySize; i++)
		{
			grid.Add(new List<char>(xSize + 1));
			for (int j = 0; j <= xSize; j++)
			{
				grid[i].Add('O');
			}
		}
		
		//Create border of polygon
		(int x, int y) previousCoord = coords[0];

		for (int i = 1; i < coords.Count; i++)
		{
			(int x, int y) toCoords =  coords[i];

			if (previousCoord.x == toCoords.x)
			{
				int minY = Math.Min(previousCoord.y, toCoords.y);
				int maxY = Math.Max(previousCoord.y, toCoords.y);
				
				for (int j = minY + 1; j < maxY; j++)
				{
					grid[j][previousCoord.x] = '|';
				}
				grid[previousCoord.y][previousCoord.x] = previousCoord.y > toCoords.y ? '|' : '-';
				grid[toCoords.y][toCoords.x] = previousCoord.y > toCoords.y ? '-' : '|';
			}
			else
			{
				int minX = Math.Min(previousCoord.x, toCoords.x);
				int maxX = Math.Max(previousCoord.x, toCoords.x);
				for (int j = minX + 1; j < maxX; j++)
				{
					grid[previousCoord.y][j] = '-';
				}
			}
			
			previousCoord = toCoords;
		}
		
		//Fill polygon
		for (int i = 0; i <= ySize; i++)
		{
			bool fill = false;
			for (int j = 0; j <= xSize; j++)
			{
				if (grid[i][j] == '|')
				{
					fill = !fill;
					continue;
				}

				if (fill) grid[i][j] = '-';
			}
		}
		
		//Calculate areas
		List<((int x, int y), (int x, int y), long area)> areas = [];
		for (int i = 0; i < coords.Count; i++)
		{
			Console.WriteLine($"{i}/{coords.Count}");
			long ax = coords[i].Item1;
			long ay = coords[i].Item2;
			for (int j = i + 1; j < coords.Count; j++)
			{
				long bx = coords[j].Item1;
				long by = coords[j].Item2;
				
				long area = (Math.Abs(ax - bx) + 1) * (Math.Abs(ay - by) + 1);
		
				areas.Add((coords[i],  coords[j], area));
			}
		}
		
		// validating areas
		areas = areas.OrderByDescending(a => a.area).ToList();
		foreach (((int x, int y), (int x, int y), long area) area in areas)
		{
			if (ValidateCoords(grid, area.Item1, area.Item2)) return area.area;
		}
		
		return 0;
	}

	private bool ValidateCoords(List<List<char>> grid, (int x, int y) coord1, (int x, int y) coord2)
	{
		int minX = Math.Min(coord1.x, coord2.x);
		int maxX = Math.Max(coord1.x, coord2.x);
		int minY = Math.Min(coord1.y, coord2.y);
		int maxY = Math.Max(coord1.y, coord2.y);
		
		
		for (int i = minX; i <= maxX ; i++)
		{
			if (grid[minY][i] == 'O' ||  grid[maxY][i] == 'O')
			{
				return false;
			}
		}
		
		for (int i = minY; i <= maxY ; i++)
		{
			if (grid[i][minX] == 'O' ||  grid[i][maxX] == 'O')
			{
				return false;
			}
		}

		return true;
	}

	private void PrintGrid(List<List<char>> grid, int maxX, int maxY)
	{
		for (int i = 0; i <= maxY; i++)
		{
			for (int j = 0; j <= maxX; j++)
			{
				Console.Write(grid[i][j]);
			}
			Console.WriteLine();
		}
	}
